fn lookup(table: &'static [(&str, &str, &str, &str)], unit: &str, style: &str, plural: &str) -> Option<&'static str> {
    table
        .binary_search_by(|(u, s, p, _)| (*u, *s, *p).cmp(&(unit, style, plural)))
        .ok()
        .map(|index| table[index].3)
}

/// The unit display pattern for a shipped locale, unit, style and plural category, along
/// the locale's parent chain.
pub fn unit_pattern(loc: &str, unit: &str, style: &str, plural: &str) -> Option<&'static str> {
    crate::cldr_locales::chain(loc).iter().find_map(|locale| {
        let table: &'static [(&str, &str, &str, &str)] = match *locale {
            "ar" => UNIT_AR,
            "ar-SA" => UNIT_AR_SA,
            "de" => UNIT_DE,
            "de-CH" => UNIT_DE_CH,
            "en" => UNIT_EN,
            "en-001" => UNIT_EN_001,
            "en-AU" => UNIT_EN_AU,
            "en-BS" => UNIT_EN_BS,
            "en-BZ" => UNIT_EN_BZ,
            "en-CA" => UNIT_EN_CA,
            "en-Dsrt" => UNIT_EN_DSRT,
            "en-IN" => UNIT_EN_IN,
            "en-KY" => UNIT_EN_KY,
            "en-PW" => UNIT_EN_PW,
            "en-Shaw" => UNIT_EN_SHAW,
            "es" => UNIT_ES,
            "es-419" => UNIT_ES_419,
            "es-AR" => UNIT_ES_AR,
            "es-CO" => UNIT_ES_CO,
            "es-DO" => UNIT_ES_DO,
            "es-MX" => UNIT_ES_MX,
            "es-PR" => UNIT_ES_PR,
            "es-PY" => UNIT_ES_PY,
            "es-US" => UNIT_ES_US,
            "fr" => UNIT_FR,
            "fr-CA" => UNIT_FR_CA,
            "fr-HT" => UNIT_FR_HT,
            "gv" => UNIT_GV,
            "hi" => UNIT_HI,
            "hi-Latn" => UNIT_HI_LATN,
            "it" => UNIT_IT,
            "ja" => UNIT_JA,
            "ko" => UNIT_KO,
            "ln" => UNIT_LN,
            "nl" => UNIT_NL,
            "pl" => UNIT_PL,
            "pt" => UNIT_PT,
            "pt-PT" => UNIT_PT_PT,
            "ru" => UNIT_RU,
            "si" => UNIT_SI,
            "sl" => UNIT_SL,
            "sr" => UNIT_SR,
            "sr-Cyrl-BA" => UNIT_SR_CYRL_BA,
            "sr-Latn" => UNIT_SR_LATN,
            "sr-Latn-BA" => UNIT_SR_LATN_BA,
            "sv" => UNIT_SV,
            "sv-FI" => UNIT_SV_FI,
            "th" => UNIT_TH,
            "zh" => UNIT_ZH,
            "zh-Hans-HK" => UNIT_ZH_HANS_HK,
            "zh-Hans-MO" => UNIT_ZH_HANS_MO,
            "zh-Hans-SG" => UNIT_ZH_HANS_SG,
            "zh-Hant" => UNIT_ZH_HANT,
            "zh-Hant-HK" => UNIT_ZH_HANT_HK,
            "zh-Latn" => UNIT_ZH_LATN,
            _ => return None,
        };
        lookup(table, unit, style, plural)
    })
}

